### Production Autonomous Rover Mechatronic Controller

Here is the complete capstone sketch. It coordinates dual actuators, enforces hardware dead-time, uses non-blocking `millis()` timing, and logs real-time telemetry to the Serial Monitor.

```cpp
#include <Servo.h>

// Hardware Pin Definitions
const int PIN_DRIVE_PWM   = 9;  // L293D Channel 1 Enable (PWM)
const int PIN_DRIVE_IN1   = 8;  // L293D Channel 1 Input 1
const int PIN_DRIVE_IN2   = 7;  // L293D Channel 1 Input 2
const int PIN_STEER_SERVO = 10; // SG90 Steering Servo Signal

// Steering Angle Constants
const int STEER_LEFT     = 45;  // 45 degrees
const int STEER_STRAIGHT = 90;  // 90 degrees center
const int STEER_RIGHT    = 135; // 135 degrees

Servo steeringServo;

// Finite State Machine Definitions
enum RoverState {
  STATE_CRUISE_FWD,
  STATE_ACTIVE_BRAKE_1,
  STATE_REVERSE_LEFT,
  STATE_ACTIVE_BRAKE_2,
  STATE_FORWARD_RIGHT,
  STATE_PARK_IDLE
};

RoverState currentState = STATE_CRUISE_FWD;
unsigned long stateStartTime = 0;

void setDrive(int speed, bool forward, bool brake = false) {
  if (brake) {
    // Regenerative Dynamic Brake
    digitalWrite(PIN_DRIVE_IN1, HIGH);
    digitalWrite(PIN_DRIVE_IN2, HIGH);
    analogWrite(PIN_DRIVE_PWM, 255);
  } else if (speed == 0) {
    // Coasting / De-energized
    digitalWrite(PIN_DRIVE_IN1, LOW);
    digitalWrite(PIN_DRIVE_IN2, LOW);
    analogWrite(PIN_DRIVE_PWM, 0);
  } else {
    // Directional Drive with PWM
    digitalWrite(PIN_DRIVE_IN1, forward ? HIGH : LOW);
    digitalWrite(PIN_DRIVE_IN2, forward ? LOW : HIGH);
    analogWrite(PIN_DRIVE_PWM, constrain(speed, 0, 255));
  }
}

void setSteering(int angle) {
  steeringServo.write(constrain(angle, 30, 150));
}

void setup() {
  pinMode(PIN_DRIVE_PWM, OUTPUT);
  pinMode(PIN_DRIVE_IN1, OUTPUT);
  pinMode(PIN_DRIVE_IN2, OUTPUT);

  // Initialize steering servo
  steeringServo.attach(PIN_STEER_SERVO);
  setSteering(STEER_STRAIGHT);

  // Ensure drive motor is stopped
  setDrive(0, true, false);

  Serial.begin(9600);
  Serial.println(F("========================================"));
  Serial.println(F("  AUTONOMOUS ROVER ACTUATOR PLATFORM    "));
  Serial.println(F("========================================"));

  stateStartTime = millis();
}

void loop() {
  unsigned long timeInState = millis() - stateStartTime;

  switch (currentState) {
    case STATE_CRUISE_FWD:
      setSteering(STEER_STRAIGHT);
      setDrive(190, true); // Cruise forward at ~75% power
      if (timeInState >= 2500) {
        Serial.println(F("[FSM] Cruise Complete -> Applying Dynamic Brake"));
        currentState = STATE_ACTIVE_BRAKE_1;
        stateStartTime = millis();
      }
      break;

    case STATE_ACTIVE_BRAKE_1:
      setDrive(0, true, true); // Active brake
      if (timeInState >= 800) {
        Serial.println(F("[FSM] Brake Complete -> Evading Obstacle: Steer Left, Drive Reverse"));
        currentState = STATE_REVERSE_LEFT;
        stateStartTime = millis();
      }
      break;

    case STATE_REVERSE_LEFT:
      setSteering(STEER_LEFT);
      setDrive(160, false); // Reverse at ~63% power
      if (timeInState >= 1800) {
        Serial.println(F("[FSM] Reverse Clear -> Braking"));
        currentState = STATE_ACTIVE_BRAKE_2;
        stateStartTime = millis();
      }
      break;

    case STATE_ACTIVE_BRAKE_2:
      setDrive(0, true, true); // Active brake
      if (timeInState >= 800) {
        Serial.println(F("[FSM] Resuming Forward Course: Steer Right"));
        currentState = STATE_FORWARD_RIGHT;
        stateStartTime = millis();
      }
      break;

    case STATE_FORWARD_RIGHT:
      setSteering(STEER_RIGHT);
      setDrive(180, true); // Forward turn
      if (timeInState >= 2000) {
        Serial.println(F("[FSM] Patrol Complete -> Rover Parked & Neutralized"));
        currentState = STATE_PARK_IDLE;
        stateStartTime = millis();
      }
      break;

    case STATE_PARK_IDLE:
      setSteering(STEER_STRAIGHT);
      setDrive(0, true, false); // De-energize
      // Remain parked safely
      break;
  }
}
```

### Code Breakdown:
- `setDrive()`: Unified actuator driver supporting forward, reverse, coasting, and dynamic braking with full PWM velocity clamping.
- `setSteering()`: Clamps angular steering between $30^\circ$ and $150^\circ$ to prevent mechanical strain against chassis steering linkages.
- `enum RoverState`: Clean state machine ensuring deterministic transitions between cruising, emergency braking, evasive reversing, and parking without blocking sensor threads.
